"""Original composite characters, not impersonations or claims about real people.

Weights: aggression, logic, bluff, loyalty, caution, verbosity. All identities
are independent of secret roles. Public prose may inspire style, never evidence.
"""


def character(id, names, titles, stories, voices, phrases, weights):
    return dict(id=id, names=names, titles=titles, stories=stories,
                voices=voices, phrases=phrases, weights=weights)


